-- SatTap leaderboard schema (Cloudflare D1 / SQLite).
-- Applied by `wrangler d1 migrations apply` (see docs/DEPLOY.md).

-- Anonymous players. Names are generated by the server, never typed by players.
CREATE TABLE players (
  id         TEXT PRIMARY KEY,          -- random UUID, kept in the player's browser
  name       TEXT NOT NULL,
  created_at INTEGER NOT NULL           -- ms since epoch
);

-- One row per player per puzzle date. Every guess updates it; `done` flips to 1 once all rounds
-- have a score, and only done runs appear on the board.
CREATE TABLE runs (
  date        TEXT NOT NULL,            -- puzzle date, YYYY-MM-DD
  player      TEXT NOT NULL,
  scores      TEXT NOT NULL,            -- JSON: {"1": {"s": 63, "h": 0}, ...} (s = score, h = hint used)
  total       INTEGER NOT NULL,
  hints       INTEGER NOT NULL,
  done        INTEGER NOT NULL,
  finished_at INTEGER,                  -- ms since epoch, set when done
  PRIMARY KEY (date, player)
) WITHOUT ROWID;

-- Leaderboard order: highest total, then fewer hints, then earliest finish.
CREATE INDEX idx_runs_board ON runs (date, done, total DESC, hints, finished_at);
